	result, err := db.Exec(ctx, "UPDATE magic_link_mail_outbox SET token_hash = $3::BYTES,   token_expires_at = $4::TIMESTAMPTZ, consumed_at = NULL, updated_at = $5::TIMESTAMPTZ WHERE id = $1::UUID AND claim_token = $2::UUID AND status = 'processing'", Id, ClaimToken, TokenHash, TokenExpiresAt, UpdatedAt)
