type RetryDeliveryRow struct {
	Status string `json:"status"`
}

func RetryDelivery(ctx context.Context, db DBTX, Id uuid.UUID, ClaimToken uuid.UUID, UpdatedAt time.Time, AvailableAt time.Time, Status int32) (*RetryDeliveryRow, error) {
	row := db.QueryRow(ctx, "UPDATE magic_link_mail_outbox SET status = CASE WHEN attempts >= $5::INT4 THEN 'dead' ELSE 'pending' END,   token_hash = NULL, token_expires_at = NULL, consumed_at = NULL,   available_at = CASE WHEN attempts >= $5::INT4 THEN available_at ELSE $4::TIMESTAMPTZ END,   lease_until = NULL, claim_token = NULL, updated_at = $3::TIMESTAMPTZ,   terminal_at = CASE WHEN attempts >= $5::INT4 THEN $3::TIMESTAMPTZ ELSE NULL END,   terminal_reason = CASE WHEN attempts >= $5::INT4 THEN 'attempts_exhausted' ELSE NULL END WHERE id = $1::UUID AND claim_token = $2::UUID AND status = 'processing' RETURNING status", Id, ClaimToken, UpdatedAt, AvailableAt, Status)
	var r RetryDeliveryRow
	if err := row.Scan(&r.Status); err != nil {
		if err == pgx.ErrNoRows {
			return nil, nil
		}
		return nil, err
	}
	return &r, nil
}
